<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
type Problem = { name: string; content: string; expected: string; source?: string; library_id?: string }
type Prover = { id: string; name: string; version: string; installed: boolean; availability_error?: string | null; executable: string }
type Result = { prover: string; problem: string; expected: string; state: string; status: string; wall_seconds: number; cpu_seconds: number | null; peak_rss_kb: number | null; output_present: boolean; error: string | null }
type Standing = { prover: string; completed: number; matches: number; claims: number; wrong: number; timeouts: number; errors: number; output_count: number; unique_matches: number; average_cpu: number | null; average_wall: number | null; maximum_rss_mb: number | null; sotac: number }
type CurrentExecution = { problem: string; problem_index: number; prover: string | null; prover_index: number | null; execution_index: number | null; phase: string; elapsed_seconds: number }
type Batch = { current_execution?: CurrentExecution | null; id: string; name: string; created: number; state: string; seconds: number; total: number; results: Result[]; problems: Problem[]; provers: string[]; manifest: unknown; error: string | null }
type Summary = { id: string; name: string; created: number; state: string; total: number; completed: number }
type Detail = { batch: Batch; standings: Standing[]; completed: number; problem_count: number; cpu_seconds: number; result_offset: number; result_limit: number; profile: {id: string; points: {x: number; y: number}[]}[] }
type LibraryInfo = { available: boolean; root?: string; version?: string; total?: number; domains?: Record<string, number>; formats?: Record<string, number>; error?: string }
type LibraryEntry = { id: string; name: string; domain: string; format: string; expected: string; title?: string; rating?: string; error?: string }
type LibraryPage = { total: number; offset: number; limit: number; entries: LibraryEntry[] }
type LibraryFile = { id: string; name: string; format: string }
type LibraryDirectory = { id: string; name: string; problems: LibraryFile[] }
const library = ref<LibraryInfo | null>(null), libraryDirectories = ref<LibraryDirectory[]>([])
const libraryQuery = ref(''), libraryDomain = ref(''), libraryFormat = ref(''), librarySelected = ref<string[]>([]), libraryBusy = ref(false), libraryMessage = ref('')
const expandedDirectories = ref<string[]>([]), directoryPages = ref<Record<string, number>>({}), libraryMetadata = ref<Record<string, LibraryEntry>>({}), directoryLoading = ref<Record<string, boolean>>({})
const appliedQuery = ref(''), appliedDomain = ref(''), appliedFormat = ref('')
const selectedLibraryIds = computed(()=>new Set(librarySelected.value))
const visibleDirectories = computed(()=>libraryDirectories.value.filter(d=>!appliedDomain.value||d.name===appliedDomain.value).map(d=>({...d,visible:d.problems.filter(p=>(!appliedFormat.value||p.format===appliedFormat.value)&&p.name.toLowerCase().includes(appliedQuery.value))})).filter(d=>d.visible.length))
function selectAllLibrary(event:Event){librarySelected.value=(event.target as HTMLInputElement).checked?libraryDirectories.value.flatMap(d=>d.problems.map(p=>p.id)):[]}
function directorySelection(directory:LibraryDirectory){const count=directory.problems.reduce((n,p)=>n+Number(selectedLibraryIds.value.has(p.id)),0);return {count,all:count===directory.problems.length,partial:count>0&&count<directory.problems.length}}
function selectDirectory(directory:LibraryDirectory,event:Event){const ids=new Set(librarySelected.value);const checked=(event.target as HTMLInputElement).checked;for(const file of directory.problems){if(checked)ids.add(file.id);else ids.delete(file.id)}librarySelected.value=[...ids]}
function directoryFiles(directory:LibraryDirectory & {visible:LibraryFile[]}){return directory.visible.slice((directoryPages.value[directory.id]??0)*20,((directoryPages.value[directory.id]??0)+1)*20)}
async function loadDirectoryPage(directory:LibraryDirectory & {visible:LibraryFile[]},pageNumber=0){directoryPages.value[directory.id]=pageNumber;const needed=directoryFiles(directory).some(p=>!libraryMetadata.value[p.id]);if(!needed)return;directoryLoading.value[directory.id]=true;try{const params=new URLSearchParams({q:appliedQuery.value,domain:directory.name,format:appliedFormat.value,offset:String(pageNumber*20)});const result=await api<LibraryPage>('/api/library/problems?'+params);for(const entry of result.entries)libraryMetadata.value[entry.id]=entry}catch(e){error.value=String(e)}finally{directoryLoading.value[directory.id]=false}}
async function toggleDirectory(directory:LibraryDirectory & {visible:LibraryFile[]}){if(expandedDirectories.value.includes(directory.id)){expandedDirectories.value=expandedDirectories.value.filter(id=>id!==directory.id)}else{expandedDirectories.value.push(directory.id);await loadDirectoryPage(directory,directoryPages.value[directory.id]??0)}}
async function searchLibrary(){appliedQuery.value=libraryQuery.value.trim().toLowerCase();appliedDomain.value=libraryDomain.value;appliedFormat.value=libraryFormat.value;directoryPages.value={};for(const directory of visibleDirectories.value){if(expandedDirectories.value.includes(directory.id))await loadDirectoryPage(directory)} }
async function importLibrary(){libraryBusy.value=true;error.value='';libraryMessage.value='';try{const result=await api<{problems:Problem[]}>('/api/library/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:librarySelected.value})});const existing=new Set(problems.value.map(p=>p.name));const additions=result.problems.filter(p=>!existing.has(p.name));const first=problems.value.length;problems.value.push(...additions);if(additions.length)selectedProblem.value=first;libraryMessage.value=`Added ${additions.length} problem reference(s). Inputs and axioms will load during the job. ${result.problems.length-additions.length} duplicate(s) skipped.`;librarySelected.value=[]}catch(e){error.value=String(e)}finally{libraryBusy.value=false}}
function preference(key:string,fallback:string){try{return localStorage.getItem(key)??fallback}catch{return fallback}}
const theme=ref(preference('atp-theme',window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'))
const layout=ref(preference('atp-layout','comfortable'))
watch([theme,layout],()=>{document.documentElement.dataset.theme=theme.value;document.documentElement.dataset.layout=layout.value;try{localStorage.setItem('atp-theme',theme.value);localStorage.setItem('atp-layout',layout.value)}catch{}},{immediate:true})
const page = ref('benchmarks'), suiteName = ref('First-order smoke suite'), seconds = ref(5)
const problems = ref<Problem[]>([]), selectedProblem = ref(0), provers = ref<Prover[]>([]), selected = ref<string[]>([])
const history = ref<Summary[]>([]), detail = ref<Detail | null>(null), busy = ref(false), error = ref(''), connected = ref(false), logs = ref<string | null>(null), logTitle = ref('')
let timer: ReturnType<typeof setInterval> | undefined
let elapsedTimer: ReturnType<typeof setInterval> | undefined
const liveTick=ref(performance.now()), executionObservedAt=ref(performance.now())
const statuses = ['Theorem', 'Unsatisfiable', 'Satisfiable', 'CounterSatisfiable', 'Unknown']
const colors = ['var(--accent)', 'var(--op)', 'var(--ok)', 'var(--warn)']
const active = computed(() => detail.value?.batch.state === 'running')
const current = computed(() => problems.value[selectedProblem.value])
const currentExecution=computed(()=>active.value?detail.value?.batch.current_execution:null)
const executionPhase=computed(()=>{switch(currentExecution.value?.phase){case 'preparing':return 'Preparing input';case 'saving':return 'Saving result';case 'input_error':return 'Recording input error';case 'running':return 'Running test';default:return 'Preparing job'}})
const executionElapsed=computed(()=>{const elapsed=Math.floor((currentExecution.value?.elapsed_seconds??0)+Math.max(0,liveTick.value-executionObservedAt.value)/1000);const minutes=Math.floor(elapsed/60);return `${String(minutes).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`})
const progress = computed(() => detail.value ? Math.round(detail.value.completed / detail.value.batch.total * 100) : 0)
const matches = computed(() => detail.value?.standings.reduce((n,s)=>n+s.matches,0) ?? 0)
const cpuTotal = computed(()=>detail.value?.cpu_seconds??0)
const wrong = computed(()=>detail.value?.standings.reduce((n,s)=>n+s.wrong,0)??0)
const nameOf = (id:string)=>provers.value.find(p=>p.id===id)?.name??id
const fmt = (n:number|null|undefined,d=3)=>n==null?'—':n.toFixed(d)
const time = (n:number)=>new Date(n*1000).toLocaleString()
function samples(){problems.value=[{name:'implication.p',expected:'Theorem',content:'% Status : Theorem\nfof(a1, axiom, a).\nfof(a2, axiom, b).\nfof(a3, axiom, (a & b) => z).\nfof(goal, conjecture, z).\n'},{name:'contradiction.p',expected:'Unsatisfiable',content:'% Status : Unsatisfiable\ncnf(positive, axiom, p).\ncnf(negative, axiom, ~p).\n'}];selectedProblem.value=0}
async function api<T>(url:string,options?:RequestInit):Promise<T>{const r=await fetch(url,options);if(!r.ok){let message=r.statusText;try{message=(await r.json()).error??message}catch{}throw Error(message)}return r.json()}
async function refreshHistory(){history.value=await api<Summary[]>('/api/batches')}
const resultPageOffset=ref<number|undefined>(undefined), pollBusy=ref(false)
const suitePage = computed(()=>Math.floor(selectedProblem.value/20))
const suiteFiles = computed(()=>problems.value.slice(suitePage.value*20,suitePage.value*20+20))
const preview = ref<Problem|null>(null), previewBusy=ref(false)
watch(()=>current.value?.library_id,()=>{preview.value=null})
async function previewCurrent(){const id=current.value?.library_id;if(!id)return;previewBusy.value=true;try{const value=await api<Problem>('/api/library/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(current.value?.library_id===id)preview.value=value}catch(e){error.value=String(e)}finally{previewBusy.value=false}}
function editableCopy(){if(!current.value||!preview.value)return;Object.assign(current.value,{...preview.value,library_id:undefined,source:undefined})}
async function load(id:string){const changed=detail.value?.batch.id!==id;if(changed)resultPageOffset.value=undefined;const params=new URLSearchParams({compact:String(!changed)});if(resultPageOffset.value!==undefined)params.set('offset',String(resultPageOffset.value));const value=await api<Detail>('/api/batches/'+id+'?'+params);if(!changed&&detail.value){value.batch.problems=detail.value.batch.problems;value.batch.manifest=detail.value.batch.manifest}executionObservedAt.value=performance.now();liveTick.value=executionObservedAt.value;detail.value=value;if(changed){suiteName.value=value.batch.name;seconds.value=value.batch.seconds;selected.value=[...value.batch.provers];problems.value=value.batch.problems.map(p=>({...p}));selectedProblem.value=0}}
function clearResults(){if(active.value||busy.value||pollBusy.value)return;detail.value=null;logs.value=null;logTitle.value='';resultPageOffset.value=undefined;error.value=''}
function clearSelectedProblems(){if(active.value||busy.value||libraryBusy.value)return;problems.value=[];selectedProblem.value=0;preview.value=null;librarySelected.value=[];libraryMessage.value='';error.value=''}
async function resultsPage(offset?:number){if(!detail.value)return;resultPageOffset.value=offset;try{await load(detail.value.batch.id)}catch(e){error.value=String(e)}}
async function run(){error.value='';busy.value=true;try{const result=await api<{id:string}>('/api/batches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:suiteName.value,seconds:seconds.value,problems:problems.value,provers:selected.value})});await load(result.id);await refreshHistory();page.value='benchmarks'}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function cancel(){if(!detail.value)return;try{await api('/api/batches/'+detail.value.batch.id+'/cancel',{method:'POST'})}catch(e){error.value=String(e)}}
async function upload(event:Event){const input=event.target as HTMLInputElement;error.value='';try{for(const file of Array.from(input.files??[])){if(file.size>1024*1024)throw Error(file.name+' is larger than 1 MB');const content=await file.text();const raw=content.match(/%\s*Status\s*:\s*(Theorem|Unsatisfiable|CounterSatisfiable|Satisfiable)/i)?.[1]??'Unknown';const expected=statuses.find(s=>s.toLowerCase()===raw.toLowerCase())??'Unknown';let name=file.name;let suffix=2;while(problems.value.some(p=>p.name===name))name=file.name+'-'+suffix++;problems.value.push({name,content,expected})}selectedProblem.value=Math.max(0,problems.value.length-1)}catch(e){error.value=String(e)}input.value=''}
function add(){let n=problems.value.length+1;while(problems.value.some(p=>p.name===`problem-${n}.p`))n++;problems.value.push({name:`problem-${n}.p`,content:'',expected:'Unknown'});selectedProblem.value=problems.value.length-1}
function remove(){problems.value.splice(selectedProblem.value,1);selectedProblem.value=Math.max(0,selectedProblem.value-1)}
async function openOutput(index:number){if(!detail.value)return;try{const r=await fetch(`/api/batches/${detail.value.batch.id}/output/${index}`);if(!r.ok)throw Error('Output unavailable');logs.value=await r.text();const row=detail.value.batch.results[index-detail.value.result_offset];logTitle.value=row?nameOf(row.prover)+' / '+row.problem:'Output'}catch(e){error.value=String(e)}}
function download(name:string,content:string,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportJson(){if(detail.value){const a=document.createElement('a');a.href=`/api/batches/${detail.value.batch.id}/export.json`;a.click()}}
function matching(row:Result){return statuses.slice(0,4).includes(row.expected)&&row.expected===row.status}
const series=computed(()=>detail.value?.profile.map((s,index)=>({...s,color:colors[index%colors.length]}))??[])
// Use the largest recorded coordinate across every prover; only empty/zero axes need a fallback.
const resultMaximum=(axis:'x'|'y')=>series.value.reduce((maximum,series)=>series.points.reduce((maximum,point)=>Math.max(maximum,point[axis]),maximum),0)
const maxX=computed(()=>resultMaximum('x')||1)
const maxY=computed(()=>resultMaximum('y')||1)
const xTicks=computed(()=>Array.from({length:5},(_,i)=>i*maxX.value/4))
const yTicks=computed(()=>{const step=Math.max(1,Math.ceil(maxY.value/4));return [...Array.from({length:Math.ceil(maxY.value/step)},(_,i)=>i*step),maxY.value]})
const axisNumber=(value:number)=>new Intl.NumberFormat(undefined,{maximumSignificantDigits:4}).format(value)
const polyline=(points:{x:number;y:number}[])=>points.map(p=>`${100+p.x/maxX.value*470},${230-p.y/maxY.value*200}`).join(' ')
onMounted(async()=>{samples();try{await api('/api/health');connected.value=true;provers.value=await api<Prover[]>('/api/provers');selected.value=provers.value.filter(p=>p.installed).map(p=>p.id);await refreshHistory();const latest=history.value[0];if(latest)await load(latest.id);library.value=await api<LibraryInfo>('/api/library');if(library.value.available)libraryDirectories.value=(await api<{directories:LibraryDirectory[]}>('/api/library/tree')).directories}catch(e){error.value='Cannot reach the Rust API. Start cargo run -p atp-server. '+String(e)}timer=setInterval(async()=>{if(detail.value?.batch.state==='running'&&!pollBusy.value){pollBusy.value=true;try{await load(detail.value.batch.id);if(!active.value)await refreshHistory()}catch(e){error.value=String(e)}finally{pollBusy.value=false}}},2000);elapsedTimer=setInterval(()=>{if(active.value)liveTick.value=performance.now()},250)})
onUnmounted(()=>{clearInterval(timer);clearInterval(elapsedTimer)})
</script>

<template>
<div class="shell">
  <div class="workspace">
    <header class="app-header">
      <a href="#" class="brand" @click.prevent="page='benchmarks'" aria-label="ATPWorkbench home">
        <svg class="brand-icon" viewBox="0 0 50 50" fill="none" aria-hidden="true"><rect x="1" y="1" width="48" height="48" rx="10"/><path d="M13 35 25 13 37 35M18 27h14"/><circle cx="25" cy="13" r="3"/><circle cx="13" cy="35" r="3"/><circle cx="37" cy="35" r="3"/></svg>
        <div class="brand-text"><h1>ATPWorkbench</h1><p class="sub">Run and compare local automated theorem provers</p></div>
      </a>
      <div class="head-meta"><span class="connection"><span :class="['dot',{online:connected}]"></span>{{connected?'Local runner connected':'Runner disconnected'}}</span><div class="head-controls">
        <button class="head-btn" @click="layout=layout==='comfortable'?'wide':'comfortable'" :title="layout==='comfortable'?'Switch to wide layout':'Switch to comfortable layout'">{{layout==='comfortable'?'Wide layout':'Comfortable layout'}}</button>
        <button class="head-btn theme-btn" @click="theme=theme==='light'?'dark':'light'" :title="theme==='light'?'Switch to dark theme':'Switch to light theme'" :aria-label="theme==='light'?'Switch to dark theme':'Switch to light theme'">
          <svg v-if="theme==='light'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/></svg>
          <svg v-else width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>
        </button>
      </div></div>
    </header>
    <nav class="tabs" aria-label="Workspace"><div class="tab-group" data-label="Run"><button :class="{selected:page==='benchmarks'}" :aria-current="page==='benchmarks'?'page':undefined" @click="page='benchmarks'">ProverBench</button><button :class="{selected:page==='suite'}" :aria-current="page==='suite'?'page':undefined" @click="page='suite'">Test suite</button></div><div class="tab-group" data-label="Manage"><button :class="{selected:page==='history'}" :aria-current="page==='history'?'page':undefined" @click="page='history'">Run history</button><button :class="{selected:page==='provers'}" :aria-current="page==='provers'?'page':undefined" @click="page='provers'">Prover registry <span class="tab-badge">{{provers.length}}</span></button></div></nav>
    <label class="tab-select"><span>Section</span><select v-model="page" aria-label="Section"><optgroup label="Run"><option value="benchmarks">ProverBench</option><option value="suite">Test suite</option></optgroup><optgroup label="Manage"><option value="history">Run history</option><option value="provers">Prover registry</option></optgroup></select></label>
    <main><div class="page-heading"><h2>{{page==='benchmarks'?'ProverBench':page==='suite'?'Test suite':page==='history'?'Run history':'Prover registry'}}</h2><p>{{page==='benchmarks'?'Run the same problems across local ATPs and compare answers, time and resource use.':page==='suite'?'Import local TPTP problems or upload your own, then define a test suite.':page==='history'?'Reopen saved experiments, inspect output and export results.':'Installed adapters are separate from the exact 92-entry catalogue target.'}}</p></div>
  <div v-if="error" class="error" role="alert">{{error}}<button @click="error=''" aria-label="Dismiss error">×</button></div>

  <template v-if="page==='benchmarks'||page==='suite'">
  <section class="card setup"><div class="section-heading"><div><span class="section-number">01</span><h2>Configure experiment</h2></div><span class="muted">Sequential execution · one core per adapter request</span></div><div class="setup-grid"><label>Suite name<input v-model="suiteName" :disabled="active" maxlength="120"></label><label>CPU budget per problem<div class="unit-input"><input v-model.number="seconds" type="number" min="1" max="300" :disabled="active"><span>seconds</span></div></label><div><label class="field-label">Provers</label><div class="prover-options"><label v-for="p in provers" :key="p.id" :class="['prover-choice',{checked:selected.includes(p.id)}]"><input v-model="selected" type="checkbox" :value="p.id" :disabled="!p.installed||active" :title="p.availability_error??undefined"><span>{{p.name}}<small :title="p.version">{{p.id==='supr'?p.version.split(' (')[0]:p.version}}</small></span></label></div></div></div><div class="setup-bottom"><div><strong>{{problems.length}}</strong> problems <span>×</span> <strong>{{selected.length}}</strong> provers <span>=</span> <strong>{{problems.length*selected.length}}</strong> executions <small>Wall cutoff: CPU budget + 5s per execution</small></div><div class="actions"><button :disabled="active||busy||pollBusy||!detail" @click="clearResults" title="Clear displayed results; saved experiments remain in Run history">Clear results</button><button :disabled="active||busy||libraryBusy||(!problems.length&&!librarySelected.length)" @click="clearSelectedProblems">Clear selected problems</button><button @click="page=page==='suite'?'benchmarks':'suite'">{{page==='suite'?'View results':'Edit suite'}}</button><button v-if="active" class="danger" @click="cancel">Cancel suite</button><button class="primary" :disabled="active||busy||!connected||!problems.length||!selected.length" @click="run"><span>▶</span> {{busy?'Starting…':'Run test suite'}}</button></div></div></section>

  <section v-if="active" class="card current-execution" aria-label="Current test">
    <div class="current-execution-main"><div class="current-execution-heading"><span class="dot online" aria-hidden="true"></span><h2>{{executionPhase}}</h2><span class="muted">Updates every 2s</span></div><div v-if="currentExecution" class="current-execution-problem" aria-live="polite" aria-atomic="true"><strong>{{currentExecution.problem}}</strong><span v-if="currentExecution.prover" class="current-execution-prover">{{nameOf(currentExecution.prover)}}</span></div><p v-else>Waiting for the runner to report the next problem…</p><p v-if="currentExecution" class="current-execution-position">Problem {{currentExecution.problem_index.toLocaleString()}} of {{detail?.problem_count.toLocaleString()}}<span v-if="currentExecution.prover_index"> · Prover {{currentExecution.prover_index}} of {{detail?.batch.provers.length}}</span><span v-if="currentExecution.execution_index"> · Execution {{currentExecution.execution_index.toLocaleString()}} of {{detail?.batch.total.toLocaleString()}}</span></p></div><div v-if="currentExecution" class="current-execution-time"><span class="muted">Elapsed wall time</span><strong>{{executionElapsed}}</strong></div>
  </section>

  <section v-if="page==='suite'" class="card suite-editor"><div class="section-heading"><div><span class="section-number">02</span><h2>Problems</h2></div><div class="actions"><button @click="samples" :disabled="active">Load examples</button><button @click="add" :disabled="active">+ Add problem</button><label class="button">Upload files<input type="file" multiple accept=".p,.tptp,.fof,.cnf,.txt" hidden @change="upload" :disabled="active"></label></div></div><div v-if="problems.length" class="editor-layout"><div class="problem-list"><button v-for="(p,i) in suiteFiles" :key="suitePage*20+i" :class="{chosen:suitePage*20+i===selectedProblem}" @click="selectedProblem=suitePage*20+i"><span>{{String(suitePage*20+i+1).padStart(2,'0')}}</span><div>{{p.name}}<small>{{p.library_id?'Library file':p.expected}}</small></div></button><div class="suite-pagination"><button :disabled="suitePage===0" @click="selectedProblem=(suitePage-1)*20">Previous</button><span>{{suitePage+1}} / {{Math.max(1,Math.ceil(problems.length/20))}}</span><button :disabled="(suitePage+1)*20>=problems.length" @click="selectedProblem=(suitePage+1)*20">Next</button></div></div><div v-if="current" class="problem-editor"><div class="editor-fields"><label>Problem name<input v-model="current.name" :disabled="active||!!current.library_id"></label><label>Expected SZS status<select v-model="current.expected" :disabled="active||!!current.library_id"><option v-for="s in statuses" :key="s">{{s}}</option></select></label><button @click="remove" :disabled="active" class="text-danger">Remove</button></div><p v-if="current.source" class="problem-source">Source: {{current.source}}</p><template v-if="current.library_id"><div class="library-input-preview"><p>This file and its expected status will load from the local library when the job reaches it.</p><div class="actions"><button :disabled="previewBusy" @click="previewCurrent">{{previewBusy?'Loading…':'Preview library input'}}</button><button v-if="preview" :disabled="active||preview.content.length>1024*1024" @click="editableCopy">Use editable copy</button></div><textarea v-if="preview" :value="preview.content" readonly spellcheck="false" aria-label="Library input preview"></textarea></div></template><textarea v-else v-model="current.content" @input="current.source=undefined" :disabled="active" spellcheck="false" aria-label="TPTP problem"></textarea><p class="muted">Unknown expectations are retained but excluded from expected-status match rankings. Use the library importer for files with include directives.</p></div></div><div v-else class="empty">No problems selected.<small>Choose problems from the TPTP library below, upload files, or load the examples.</small></div></section>

  <section v-if="page==='suite'" class="card library-browser"><div class="section-heading"><div><span class="section-number">03</span><h2>TPTP library</h2></div><span class="muted">{{library?.available?`${library.total?.toLocaleString()} local problems`:'Not configured'}}</span></div>
    <template v-if="library?.available"><div class="library-intro"><p><strong>{{library.version}}</strong><br>Browse the full problem library. CASC competition sets are selected subsets.</p><p class="path">{{library.root}}</p></div>
    <form class="library-filters" @submit.prevent="searchLibrary()"><label>Problem filename<input v-model="libraryQuery" placeholder="e.g. PUZ001" maxlength="80"></label><label>Domain<select v-model="libraryDomain"><option value="">All domains</option><option v-for="(count,domain) in library.domains" :key="domain" :value="domain">{{domain}} ({{count}})</option></select></label><label>Language<select v-model="libraryFormat"><option value="">All languages</option><option v-for="(count,format) in library.formats" :key="format" :value="format">{{format}} ({{count}})</option></select></label><button type="submit" :disabled="libraryBusy">{{libraryBusy?'Loading…':'Search'}}</button></form>
    <p class="library-selection-help">Select every library problem with the header checkbox, or expand directories to choose files. Directory selections include all pages and filtered files.</p>
    <div class="table-wrap library-tree"><table aria-label="TPTP problem directories"><thead><tr><th><input type="checkbox" aria-label="Select all library problems" :checked="!!library?.total&&librarySelected.length===library.total" :indeterminate="librarySelected.length>0&&librarySelected.length!==(library?.total??0)" :disabled="active||libraryBusy" @change="selectAllLibrary"></th><th>Directory / problem</th><th>Language</th><th>Expected</th><th>Rating</th></tr></thead><tbody>
      <template v-for="directory in visibleDirectories" :key="directory.id">
        <tr class="directory-row"><td><input type="checkbox" :checked="directorySelection(directory).all" :indeterminate="directorySelection(directory).partial" :aria-label="`Select all problems in ${directory.name}`" :disabled="active||libraryBusy" @change="selectDirectory(directory,$event)"></td><td colspan="4"><div class="directory-heading"><button class="directory-toggle" :aria-expanded="expandedDirectories.includes(directory.id)" :aria-label="`${expandedDirectories.includes(directory.id)?'Collapse':'Expand'} ${directory.name} directory`" @click="toggleDirectory(directory)"><span class="directory-chevron" aria-hidden="true">{{expandedDirectories.includes(directory.id)?'▾':'▸'}}</span><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 7V5h7l2 2h9v13H3Z"/></svg><strong>{{directory.name}}</strong></button><span class="muted">{{directory.problems.length.toLocaleString()}} .p problems<span v-if="directory.visible.length!==directory.problems.length"> · {{directory.visible.length}} matching</span></span><span v-if="directorySelection(directory).count" class="directory-selected">{{directorySelection(directory).count}} selected</span></div></td></tr>
        <template v-if="expandedDirectories.includes(directory.id)"><tr v-for="file in directoryFiles(directory)" :key="file.id" class="problem-row"><td><input type="checkbox" v-model="librarySelected" :value="file.id" :aria-label="`Select ${file.name}`" :disabled="active||libraryBusy||!!libraryMetadata[file.id]?.error"></td><td class="tree-problem-name"><strong>{{file.name}}</strong><small class="library-title">{{libraryMetadata[file.id]?.title??libraryMetadata[file.id]?.error}}</small></td><td>{{file.format}}</td><td>{{libraryMetadata[file.id]?.expected??'—'}}</td><td class="muted" :title="libraryMetadata[file.id]?.rating">{{libraryMetadata[file.id]?.rating?.split(',')[0]??'—'}}</td></tr>
        <tr class="directory-pagination"><td></td><td colspan="4"><div class="actions"><button :disabled="directoryLoading[directory.id]||!(directoryPages[directory.id]??0)" :aria-label="`Previous problems in ${directory.name}`" @click="loadDirectoryPage(directory,(directoryPages[directory.id]??0)-1)">Previous</button><span class="muted">{{(directoryPages[directory.id]??0)*20+1}}–{{Math.min(((directoryPages[directory.id]??0)+1)*20,directory.visible.length)}} of {{directory.visible.length.toLocaleString()}}<span v-if="directoryLoading[directory.id]"> · Loading metadata…</span></span><button :disabled="directoryLoading[directory.id]||((directoryPages[directory.id]??0)+1)*20>=directory.visible.length" :aria-label="`Next problems in ${directory.name}`" @click="loadDirectoryPage(directory,(directoryPages[directory.id]??0)+1)">Next</button></div></td></tr></template>
      </template><tr v-if="!visibleDirectories.length"><td colspan="5" class="empty">No matching problems.</td></tr>
    </tbody></table></div>
    <div class="library-bottom"><div class="actions"><span class="muted">{{librarySelected.length.toLocaleString()}} selected · {{visibleDirectories.length}} directories</span><button :disabled="active||libraryBusy||!librarySelected.length" @click="librarySelected=[]">Clear selection</button></div><button class="primary" :disabled="active||libraryBusy||!librarySelected.length" @click="importLibrary">{{libraryBusy?'Importing…':`Add selected (${librarySelected.length.toLocaleString()})`}}</button></div><p v-if="libraryMessage" class="library-message" role="status">{{libraryMessage}}</p><p class="footnote">One job can contain the entire library. Problem files and required axioms load one at a time during execution. Adding a selection does not start the job.</p></template>
    <p v-else class="footnote">{{library?.error??'Configure ATP_TPTP_ROOT or data/library.json, then restart the Rust server to browse your local TPTP library.'}}</p>
  </section>



  <template v-if="page==='benchmarks'"><div class="metrics"><article><span>PROBLEMS IN SUITE</span><strong>{{detail?.problem_count??problems.length}}</strong><small>{{detail?.batch.name??suiteName}}</small></article><article><span>EXPECTED-STATUS MATCHES</span><strong>{{matches}}<em>/ {{detail?.batch.total??'—'}}</em></strong><small>Prover claims · not proof-validated</small></article><article><span>RECORDED CPU TIME</span><strong>{{fmt(cpuTotal,2)}}<em>s</em></strong><small>User + system · unavailable measurements omitted</small></article><article><span>EXPERIMENT STATUS</span><strong class="state-value">{{detail?.batch.state??'Ready'}}</strong><small>{{detail?`${detail.completed} of ${detail.batch.total} executions complete`:'Configure a suite to get started'}}</small></article></div>
  <section class="card results"><div class="section-heading"><div><span class="section-number">02</span><h2>Leaderboard</h2><span v-if="active" class="running">Running</span></div><div class="actions"><button :disabled="!detail" @click="exportJson">Export JSON</button><a v-if="detail" :href="`/api/batches/${detail.batch.id}/export.csv`" class="button">↓ Export CSV</a></div></div><div v-if="detail" class="progress"><span :style="{width:progress+'%'}"></span></div><div class="table-wrap"><table><thead><tr><th>Rank / prover</th><th>Matches</th><th>Avg CPU s</th><th>Avg wall s</th><th>Peak MiB</th><th>Unique</th><th>SotAC*</th><th>Timeouts</th><th>Errors / wrong</th></tr></thead><tbody><tr v-for="(s,i) in detail?.standings??[]" :key="s.prover"><td><span class="rank">{{String(i+1).padStart(2,'0')}}</span><strong>{{nameOf(s.prover)}}</strong></td><td><span class="match-count">{{s.matches}}</span><span class="muted"> / {{detail?.problem_count}}</span></td><td>{{fmt(s.average_cpu)}}</td><td>{{fmt(s.average_wall)}}</td><td>{{fmt(s.maximum_rss_mb,1)}}</td><td>{{s.unique_matches}}</td><td>{{fmt(s.sotac,2)}}</td><td>{{s.timeouts}}</td><td :class="{'text-danger':s.errors||s.wrong}">{{s.errors}} / {{s.wrong}}</td></tr><tr v-if="!detail"><td colspan="9" class="empty">Your first experiment starts here.<small>Run the included smoke suite to compare your installed provers.</small></td></tr></tbody></table></div><p class="footnote">CASC-inspired ranking: expected-status matches, then average CPU time on matching answers. Proof/model output is recorded, but acceptance is not validated. *SotAC averages the fraction of selected systems that did not match, excluding universally matched problems.</p><p v-if="wrong" class="wrong-alert">{{wrong}} answer(s) conflict with expected statuses. Investigate these runs before drawing conclusions.</p></section>
  <div class="analysis-grid"><section class="card"><div class="section-heading"><div><span class="section-number">03</span><h2>Performance profile</h2></div><span class="muted">Cumulative CPU time</span></div><div class="legend"><span v-for="s in series" :key="s.id"><i :style="{background:s.color}"></i>{{nameOf(s.id)}}</span></div><svg viewBox="0 0 600 300" class="performance-chart" role="img" aria-label="Cumulative matching problems by CPU time"><text class="axis-title" x="18" y="130" text-anchor="middle" transform="rotate(-90 18 130)">Expected-status matches</text><g v-for="value in yTicks" :key="value"><line x1="100" x2="570" :y1="230-value/maxY*200" :y2="230-value/maxY*200" stroke="var(--line)"/><text x="84" :y="235-value/maxY*200" text-anchor="end">{{value.toLocaleString()}}</text></g><g v-for="(value,i) in xTicks" :key="i"><line :x1="100+value/maxX*470" :x2="100+value/maxX*470" y1="230" y2="236" stroke="var(--line)"/><text :x="100+value/maxX*470" y="260" :text-anchor="i===0?'start':i===4?'end':'middle'">{{axisNumber(value)}}s</text></g><polyline v-for="s in series" :key="s.id" :points="polyline(s.points)" fill="none" :stroke="s.color" stroke-width="2.5"/><text class="axis-title" x="335" y="289" text-anchor="middle">Cumulative CPU seconds · expected-status matches</text></svg></section><section class="card methodology"><h2>Benchmark notes</h2><p>Every selected prover receives every problem, under the same requested time budget. Matches depend on your expected status.</p><div><span>Execution</span><strong>Local · sequential</strong></div><div><span>Proof validation</span><strong>Not yet implemented</strong></div><div><span>Exact catalogue target</span><strong>0 / 92 verified setups</strong></div><a href="https://tptp.org/CASC/J13/Design.html" target="_blank" rel="noreferrer">Read the CASC evaluation rules ↗</a></section></div>
  <section v-if="detail" class="card"><div class="section-heading"><div><span class="section-number">04</span><h2>Individual executions</h2></div><span class="muted">{{detail.batch.name}} · {{time(detail.batch.created)}}</span></div><div class="table-wrap"><table><thead><tr><th>Problem</th><th>Prover</th><th>Expected</th><th>Reported</th><th>CPU / wall s</th><th>Proof/model block</th><th>Output</th></tr></thead><tbody><tr v-for="(r,i) in detail.batch.results" :key="i"><td>{{r.problem}}</td><td>{{nameOf(r.prover)}}</td><td>{{r.expected}}</td><td><span :class="['status',matching(r)?'success':r.status==='Timeout'?'timeout':r.error?'failure':'neutral']">{{r.status}}</span></td><td>{{fmt(r.cpu_seconds)}} / {{fmt(r.wall_seconds)}}</td><td>{{r.output_present?'Present · unchecked':'Not found'}}</td><td><button class="small" @click="openOutput(i+detail.result_offset)">View log ↗</button></td></tr></tbody></table></div><div class="library-bottom"><div class="actions"><button :disabled="detail.result_offset===0" @click="resultsPage(Math.max(0,detail.result_offset-100))">Previous results</button><span class="muted">{{detail.completed?detail.result_offset+1:0}}–{{detail.result_offset+detail.batch.results.length}} of {{detail.completed.toLocaleString()}}</span><button :disabled="detail.result_offset+100>=detail.completed" @click="resultsPage(detail.result_offset+100)">Next results</button></div><button :disabled="resultPageOffset===undefined" @click="resultsPage()">Follow latest</button></div><p class="footnote">Leaderboard and performance profile cover the whole job. This table displays up to 100 executions per page.</p><p v-if="detail.batch.error" class="wrong-alert">{{detail.batch.error}}</p></section>
  </template></template>

  <section v-if="page==='history'" class="card"><div class="section-heading"><h2>Saved experiments</h2><button @click="refreshHistory">Refresh</button></div><table><thead><tr><th>Experiment</th><th>Started</th><th>Status</th><th>Executions</th><th></th></tr></thead><tbody><tr v-for="b in history" :key="b.id"><td><strong>{{b.name}}</strong></td><td>{{time(b.created)}}</td><td>{{b.state}}</td><td>{{b.completed}} / {{b.total}}</td><td><button @click="load(b.id).then(()=>page='benchmarks').catch(e=>error=String(e))">Open results</button></td></tr><tr v-if="!history.length"><td colspan="5" class="empty">No experiments saved yet.</td></tr></tbody></table></section>
  <section v-if="page==='provers'" class="card"><div class="section-heading"><h2>Installed adapters</h2><span class="muted">Exact online versions are not certified</span></div><table><thead><tr><th>Prover</th><th>Version</th><th>Availability</th><th>Executable</th></tr></thead><tbody><tr v-for="p in provers" :key="p.id"><td><strong>{{p.name}}</strong></td><td :title="p.version">{{p.id==='supr'?p.version.split(' (')[0]:p.version}}</td><td><span :class="['status',p.installed?'success':'failure']">{{p.installed?'Installed':p.availability_error?'Unavailable':'Missing'}}</span></td><td class="path">{{p.executable}}<small v-if="p.availability_error" class="library-title">{{p.availability_error}}</small></td></tr></tbody></table><p class="footnote">These are explicitly configured local adapters. The reference catalogue describes 92 target setups; it does not install them.</p></section>
  <footer>ATPWorkbench / ProverBench<span>Local execution. Reproducible experiments.</span></footer>
  </main></div>
  <div v-if="logs!==null" class="modal-backdrop" @click.self="logs=null"><section class="log-modal" role="dialog" aria-modal="true" aria-label="Prover output"><div class="section-heading"><h2>{{logTitle}}</h2><div class="actions"><button @click="download('prover-output.txt',logs??'','text/plain')">Download log</button><button @click="logs=null" aria-label="Close output">Close ×</button></div></div><pre>{{logs}}</pre></section></div>
</div>
</template>
